use super::*;
use crate::tooltip::{Side, tooltip};
use gpui::{Anchor, Edges, anchored, deferred};

const ACTIONS: [(&str, Option<&str>, bool); 9] = [
    ("Rename", Some("⌥⌘R"), false),
    ("Pin", Some("⌥⌘P"), false),
    ("New side chat", Some("⌥⌘S"), false),
    ("Fork", None, true),
    ("Share", None, false),
    ("Copy", None, true),
    ("Open in new window", None, false),
    ("Open in", None, true),
    ("Archive", Some("⇧⌘A"), false),
];

impl ThreadView {
    pub fn header_title(&self) -> SharedString {
        if self.title.is_empty() {
            "Chat".into()
        } else {
            self.title.clone()
        }
    }

    pub fn chat_action_labels(&self) -> Option<impl Iterator<Item = &'static str>> {
        self.chat_actions
            .as_ref()
            .map(|_| ACTIONS.iter().map(|item| item.0))
    }

    fn close_chat_actions(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.chat_actions = None;
        if let Some(trigger) = &self.chat_actions_trigger {
            trigger.focus(window, cx);
        }
        cx.notify();
    }

    fn actions_popup(&self, cx: &Context<Self>) -> impl IntoElement {
        let t = cx.theme();
        let hover = t.menu_item_hover;
        let content = crate::composer::popover(t, 220., |mut menu| {
            for (index, &(label, shortcut, submenu)) in ACTIONS.iter().enumerate() {
                if matches!(index, 2 | 4 | 6 | 8) {
                    menu = menu.child(
                        div()
                            .h(px(9.))
                            .flex()
                            .items_center()
                            .child(div().h(px(1.)).w_full().bg(t.border)),
                    );
                }
                menu = menu.child(
                    div()
                        .id(("chat-action", index))
                        .h(px(28.5625))
                        .px(px(8.))
                        .rounded(px(12.))
                        .flex()
                        .items_center()
                        .gap(px(6.))
                        .hover(move |s| s.bg(hover))
                        .child(
                            div()
                                .relative()
                                .size(px(16.))
                                .flex_none()
                                .child(action_icon(index, t.text)),
                        )
                        .child(text(label, 13., 18.5714, 430., t.text).flex_1())
                        .when_some(shortcut, |d, keys| {
                            d.child(text(keys, 12., 16., 430., t.text_tertiary))
                        })
                        .when(submenu, |d| {
                            d.child(icon("thread-chevron-right", 16., t.text_tertiary))
                        }),
                );
            }
            menu
        });
        let menu = div()
            .id("chat-actions-menu")
            .occlude()
            .when_some(self.chat_actions.as_ref(), |d, focus| d.track_focus(focus))
            .on_key_down(cx.listener(|view, event: &gpui::KeyDownEvent, window, cx| {
                if event.keystroke.key == "escape" {
                    view.close_chat_actions(window, cx);
                    cx.stop_propagation();
                }
            }))
            .on_mouse_down_out(cx.listener(|view, _, _, cx| {
                if !view.chat_actions_hovered {
                    view.chat_actions = None;
                    cx.notify();
                }
            }))
            .child(content);
        deferred(
            div().absolute().top(px(30.)).left_0().child(
                anchored()
                    .anchor(Anchor::TopLeft)
                    .snap_to_window_with_margin(Edges::all(px(7.)))
                    .child(menu),
            ),
        )
        .with_priority(1)
    }

    /// The thread's part of the window titlebar (`Chat toolbar`): project icon and title, then
    /// `Chat actions` and `Toggle summary`, laid over the shell's titlebar (open-sidebar
    /// layout) from the main panel's left edge to the shell's `New tab` group.
    pub fn titlebar_header(&self, cx: &Context<Self>) -> Div {
        div()
            .absolute()
            .top_0()
            .left(Theme::SIDEBAR_WIDTH)
            .right(px(43.))
            // Chromium composites the `group/titlebar` (it overlaps composited layers): text
            // blits into its transparent tile.
            .layer()
            .child(self.header(cx))
    }

    pub(super) fn header(&self, cx: &Context<Self>) -> Div {
        let t = cx.theme();
        div()
            .relative()
            .h(Theme::TITLEBAR_HEIGHT)
            .flex()
            .items_center()
            .justify_between()
            .gap(px(8.))
            .pl(px(8.))
            .pr(px(6.))
            // Divider between the sidebar's and the thread's titlebar parts.
            .child(
                div()
                    .absolute()
                    .left_0()
                    .top(px(12.))
                    .w(px(1.))
                    .h(px(20.))
                    .bg(over(t.border, layout_color(t))),
            )
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .flex()
                    .items_center()
                    .gap(px(4.))
                    .child(
                        div()
                            .size(px(28.))
                            .flex_none()
                            .flex()
                            .items_center()
                            .justify_center()
                            .child(icon("thread-project", 16., t.text)),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .ml(px(-2.))
                            .px(px(6.))
                            .overflow_hidden()
                            .child(
                                text(self.header_title(), 14., 24., 500., t.text).text_ellipsis(),
                            ),
                    ),
            )
            .child(
                div()
                    .flex()
                    .flex_none()
                    .items_center()
                    .gap(px(6.))
                    .child(
                        icon_button(
                            "chat-actions",
                            icon("thread-chat-actions", 16., t.text_tertiary),
                            t,
                        )
                        .when(self.chat_actions.is_some(), |d| d.bg(t.ghost_hover))
                        .when_some(self.chat_actions_trigger.as_ref(), |d, focus| {
                            d.track_focus(focus)
                        })
                        .on_hover(cx.listener(|view, hovered: &bool, _, _| {
                            view.chat_actions_hovered = *hovered;
                        }))
                        .on_click(cx.listener(|view, _, window, cx| {
                            if view.chat_actions.is_some() {
                                view.close_chat_actions(window, cx);
                            } else {
                                view.chat_actions_trigger
                                    .get_or_insert_with(|| cx.focus_handle());
                                let focus = cx.focus_handle();
                                focus.focus(window, cx);
                                view.chat_actions = Some(focus);
                                cx.notify();
                            }
                        }))
                        .when(self.chat_actions.is_some(), |d| {
                            d.child(self.actions_popup(cx))
                        }),
                    )
                    .child(tooltip(
                        if self.summary_open {
                            // Pressed: `bg-text/10` squircle, primary icon.
                            div()
                                .id("toggle-summary")
                                .relative()
                                .size(px(28.))
                                .flex()
                                .items_center()
                                .justify_center()
                                .on_mouse_down(gpui::MouseButton::Left, |_, _, cx| {
                                    cx.stop_propagation()
                                })
                                .child(shapes::decoration(shapes::Decoration {
                                    radius: Corners::all(px(12.5)),
                                    corner: shapes::Corner::Squircle,
                                    // Translucent in the titlebar's transparent layer.
                                    fill: Some(t.text_alpha_10),
                                    ..Default::default()
                                }))
                                .child(icon("thread-summary", 16., t.text))
                        } else {
                            icon_button(
                                "toggle-summary",
                                icon("thread-summary", 16., t.text_tertiary),
                                t,
                            )
                        }
                        .on_click(cx.listener(|view, _, _, cx| {
                            view.summary_open ^= true;
                            cx.notify();
                        })),
                        "Toggle summary",
                        None,
                        Side::Bottom,
                    )),
            )
    }
}

