fn action_icon(index: usize, color: Hsla) -> impl IntoElement {
    gpui::canvas(
        |_, _, _| {},
        move |bounds, (), window, cx| {
            if !shapes::paint_icon(
                ACTION_ICONS[index],
                ACTIONS[index].0,
                bounds,
                false,
                color,
                None,
                window,
                cx,
            ) {
                window
                    .paint_svg(
                        bounds,
                        ACTIONS[index].0.into(),
                        Some(ACTION_ICONS[index]),
                        gpui::TransformationMatrix::default(),
                        color,
                        cx,
                    )
                    .ok();
            }
        },
    )
    .absolute()
    .left(px(-1.))
    .top(px(-1.))
    .size(px(18.))
}
